import random
rnd = random.Random(0)
kv = sol.VersionedKV()
keys = ["k%d" % i for i in range(20)]
log = []
for i in range(900):
    op = rnd.random()
    k = rnd.choice(keys)
    if op < 0.45:
        kv.set(k, i)
    elif op < 0.6:
        try:
            kv.delete(k)
            log.append("del")
        except KeyError:
            log.append("nodel")
    elif op < 0.75:
        log.append(kv.commit())
    elif op < 0.85 and kv.latest() > 0:
        v = rnd.randrange(0, kv.latest() + 1)
        kv.rollback(v)
        log.append(["rb", v])
    else:
        log.append(kv.has(k))
    if i % 100 == 0:
        log.append([kv.latest(), sorted(k2 for k2 in keys if kv.has(k2))])
snaps = []
for v in range(1, kv.latest() + 1):
    row = []
    for k2 in keys:
        try:
            row.append([k2, kv.get_at(k2, v)])
        except KeyError:
            pass
    snaps.append(row)
result = [log, snaps, kv.latest()]
